# The sheet's descendants (its children, their children, ...), each once, nearest first. 404 for an id never loaded.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.setting.RespondWithDescendants
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.setting;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The sheet's descendants: its children (the sheets naming it as their parent), their children, and so on, each
 *  once, nearest first. */
public class RespondWithDescendants {
    public void respond(@PathVariable("sheetId") String sheetId, SettingRepository settings,
            ObjectResponse<List<String>> response) {
        String id = sheetId.trim();
        Set<String> seen = new LinkedHashSet<>();
        seen.add(id);
        Deque<String> next = new ArrayDeque<>(List.of(id));
        while (!next.isEmpty()) {
            for (String child : settings.children(next.removeFirst())) {
                if (seen.add(child)) {
                    next.addLast(child);
                }
            }
        }
        seen.remove(id);
        response.send(new ArrayList<>(seen));
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJsonNow } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheet';
import type { Claim } from '../claims/claims';
import type { Person } from '../people/people';
import { sheetDueTotal, sheetOverdueTotal, sumDue, type Rate } from '../rates/rates';
import { floorOf, lateOf, type Settings } from '../settings/settings';
import type { Sheet } from '../sheet/sheet';

/** One read of a sheet as the store holds it now, whatever date this screen shows the sheet as of. Keyed under the
 *  sheet, so a load of that sheet re-reads it. */
function useNow<T>(sheetId: string, part: string) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'now', part],
    queryFn: () => getJsonNow<T>(`/api/sheets/${encodeURIComponent(sheetId)}${part === '' ? '' : `/${part}`}`),
  });
}

type Figures = { people: number; due: string; overdue: string };

/** Adds the figures of sheets[at] to `sum`, then goes on to the next sheet; past the last, shows the figures added
 *  up. One component per sheet keeps each sheet's reads in hooks of its own. */
function Accumulate({ sheets, at, sum }: { sheets: string[]; at: number; sum: Figures }) {
  if (at >= sheets.length) return <Shown figures={sum} />;
  return <SheetFigures key={sheets[at]} sheets={sheets} at={at} sum={sum} />;
}

/** A sheet's figures as it shows them now: its people (retired ones included), its due-total and its overdue-total
 *  (as its header shows them). */
function SheetFigures({ sheets, at, sum }: { sheets: string[]; at: number; sum: Figures }) {
  const sheetId = sheets[at];
  const people = useNow<Person[]>(sheetId, 'people').data ?? [];
  const claims = useNow<Claim[]>(sheetId, 'claims').data ?? [];
  const rates = useNow<Rate[]>(sheetId, 'rates').data ?? [];
  const settings = useNow<Settings>(sheetId, 'settings').data;
  const today = useNow<Sheet>(sheetId, '').data?.today ?? '';
  const floor = floorOf(settings);
  const late = lateOf(settings, today, claims, people);
  const next: Figures = {
    people: sum.people + people.length,
    due: sumDue([sum.due, sheetDueTotal(people, claims, rates, today, floor, late, settings?.cap ?? '')]),
    overdue: sumDue([sum.overdue, sheetOverdueTotal(people, claims, rates, late, floor)]),
  };
  return <Accumulate sheets={sheets} at={at + 1} sum={next} />;
}

function Shown({ figures }: { figures: Figures }) {
  return (
    <p data-testid="consolidated">
      Consolidated: people <strong data-testid="consolidated-people-count">{figures.people}</strong>{' '}
      due total <strong data-testid="consolidated-due-total">{figures.due}</strong>{' '}
      overdue total <strong data-testid="consolidated-overdue-total">{figures.overdue}</strong>
    </p>
  );
}

/** Consolidated figures over the sheet and all its descendants (its children — the sheets naming it as their
 *  parent — theirs, and so on), as the store holds them now: the people, and each sheet's due-total and
 *  overdue-total (as that sheet shows them) added up. A sheet with no children shows its own. */
function Consolidated({ sheetId }: { sheetId: string; user: string }) {
  const descendants = useNow<string[]>(sheetId, 'descendants').data ?? [];
  return <Accumulate sheets={[sheetId, ...descendants]} at={0} sum={{ people: 0, due: '0.00', overdue: '0.00' }} />;
}

export const contribution = SheetBody.fill({ order: -1, Component: Consolidated });
