    /** Whether another person on this sheet (other than exceptId, when given) has this name, or anyone on the sheet
     *  has it as an alias, compared without regard to case and ignoring surrounding spaces. */
    public boolean nameInUse(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT (SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?) "
                        + "+ (SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?)))",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId, sheetId, name);
        return n != null && n > 0;
    }

    /** The other sheets of the sheet's tree, among those that exist: its ancestors (its parent, its parent's parent,
     *  and so on) and its descendants (the sheets naming it as their parent, their children, and so on). */
    public List<String> tree(String sheetId) {
        java.util.Set<String> seen = new java.util.LinkedHashSet<>();
        seen.add(sheetId);
        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) {
        }
        java.util.Deque<String> next = new java.util.ArrayDeque<>(List.of(sheetId));
        while (!next.isEmpty()) {
            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent = ? ORDER BY id", String.class,
                    next.removeFirst())) {
                if (seen.add(child)) {
                    next.addLast(child);
                }
            }
        }
        seen.remove(sheetId);
        return seen.stream().filter(id -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?",
                Integer.class, id) > 0).toList();
    }

    private String parentOf(String sheetId) {
        return jdbc.query("SELECT parent FROM sheet WHERE id = ?", rs -> rs.next() ? rs.getString(1) : null, sheetId);
    }

    /** The first of the sheets that has this as a name or an alias (compared as nameInUse compares), or null. */
    public String sheetUsing(List<String> sheetIds, String name) {
        return sheetIds.stream().filter(other -> nameInUse(other, name, null)).findFirst().orElse(null);
    }

    /** The other sheet of the sheet's tree (see tree) that has this as a name or an alias, or null when none has. */
    public String sheetInTreeUsing(String sheetId, String name) {
        return sheetUsing(tree(sheetId), name);
    }

    /** Whether the person's name, or one of their aliases, is a name or alias on one of the sheets (their sheet's
     *  tree, see tree). */
    public boolean clashing(Person person, List<String> tree) {
        return !tree.isEmpty() && (sheetUsing(tree, person.name()) != null
                || person.aliases().stream().anyMatch(a -> sheetUsing(tree, a) != null));
    }

    /** Give the person an alias (stored trimmed). Leaves the version alone: an alias is not an edit of the person. */
    public void alias(Person person, String alias) {
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, made_on) VALUES (?, ?, ?, "
                + "(SELECT today FROM sheet WHERE id = ?))", person.sheetId(), person.id(), alias.trim(), person.sheetId());
    }

    /** The aliases of the sheet's people by person, each sorted as names are compared; only those given while the
     *  sheet's today was on or before `end`, when one is given. */
    private Map<Long, List<String>> aliases(String sheetId, LocalDate end) {
        return jdbc.query("SELECT person_id, alias FROM person_alias WHERE sheet_id = ? "
                + "AND (CAST(? AS DATE) IS NULL OR made_on IS NULL OR made_on <= ?) ORDER BY person_id, alias_key, id",
                ALIAS_ROW, sheetId, end, end).stream().collect(Collectors.groupingBy(AliasRow::personId,
                        Collectors.mapping(AliasRow::alias, Collectors.toList())));
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's people, in the order they were added (as they stood at the end of the as-of date, when one is given). */
public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, PersonRepository repository,
            ObjectResponse<List<PersonResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        List<Person> people = end != null ? repository.listAsOf(id, end) : repository.list(id);
        List<String> tree = repository.tree(id);
        response.send(people.stream().map(p -> PersonResponse.from(p, repository.clashing(p, tree))).toList());
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { counts, lateFrom, live, overdue, type Claim } from '../claims/claims';
import { gradeOn, type Person } from '../people/people';
import type { DatedValue } from '../settings/settings';

/** A grade's rate on the sheet: a percent with two decimals, in force from its from-date (yyyy-mm-dd, or
 *  null: from the beginning of time) through its to-date (null: with no end). A grade may have several, one
 *  per from-date; none when it has no rate. `level` is where it comes from: 0 the sheet's own, 1 its parent
 *  sheet's, 2 the parent's parent's, 3 the one above that. */
export type Rate = { grade: string; rate: string; from: string | null; to: string | null; level?: number };

/** Of the rates, the sheet's own (not its parents'). */
export function ownRates(rates: Rate[]): Rate[] {
  return rates.filter((r) => (r.level ?? 0) === 0);
}

export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

/** The sheet's rates, every grade's every from-date, then its parents' (up to three levels up). */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
  });
}

/** A grade's rate in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or before
 *  it, a rate with no from-date applying from the beginning of time; undefined when none applies, or that
 *  one's to-date is before the date. When the sheet's own has none, the nearest parent's that has one. */
export function rateOn(rates: Rate[], grade: string, date: string): string | undefined {
  const levels = [...new Set(rates.map((r) => r.level ?? 0))].sort((a, b) => a - b);
  for (const level of levels) {
    const rate = levelRateOn(rates.filter((r) => (r.level ?? 0) === level), grade, date);
    if (rate !== undefined) return rate;
  }
  return undefined;
}

/** Of one sheet's rates, the grade's in force on the date (see rateOn). */
function levelRateOn(rates: Rate[], grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (!found || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  if (found?.to != null && found.to < date) return undefined;
  return found?.rate;
}

/** A grade's rate in force on a date, or undefined when none applies (or the rates are still loading). */
export function useRateFor(sheetId: string, grade: string, date: string): string | undefined {
  return rateOn(useRates(sheetId).data ?? [], grade, date);
}

/** A two-decimal amount (may be negative) as whole cents, exactly. */
export function toCents(amount: string): bigint {
  const trimmed = amount.trim();
  const negative = trimmed.startsWith('-');
  const [whole, frac = ''] = (negative ? trimmed.slice(1) : trimmed).split('.');
