    expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "12.50", "note": "tpl"})).toBe(true);
    await ui.setSetting(pg_uma, "fiscal-start-month", "7");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50", "from": "2026-03-16", "to": "2026-03-25"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "20", "tags": "b, a"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "tags": "a"}));
    expect(await ui.addPool(pg_uma, "P1")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "70.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "20.00"})).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.merge(pg_vic, p_ben, "Cam")).toBe(true);
    expect(await ui.watch(pg_vic, p_cam, true)).toBe(true);
    expect(await ui.setRate(pg_vic, {"grade": "A", "pct": "20.00", "from": "2026-03-16"})).toBe(true);
    const c_cam_0 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "10.35", "date": "2026-03-15"}));
    expect(await ui.hold(pg_vic, p_cam, {"from": "2026-03-28"})).toBe(true);
    expect(await ui.claimAction(pg_vic, c_cam_0, "delete")).toBe(true);
    expect(await ui.claimAction(pg_vic, c_cam_0, "restore")).toBe(true);
    expect(await ui.statement(pg_vic, p_cam)).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_cam_0, "open")).toBe(true);
    expect(await ui.importPeople(pg_vic, "Dot,B\nFay,A,,")).toMatchObject({"added": 2, "updated": 0});
    const p_dot = await ui.personId(pg_vic, "Dot");
    const p_fay = await ui.personId(pg_vic, "Fay");
    expect(await ui.setRate(pg_vic, {"grade": "B", "pct": "33.33", "from": "2026-03-10"})).toBe(true);
    expect(await ui.setRate(pg_vic, {"grade": "C", "pct": "20.00"})).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.redate(pg_vic, c_cam_0, "2026-04-02")).toBe(true);
    expect(await ui.setRate(pg_vic, {"grade": "B", "pct": "20.00"})).toBe(true);
    expect(await ui.statement(pg_vic, p_dot)).toBe(true);
    await ui.refresh(pg_vic);
